<template><div class="page"><div class="head"><div><h2>实时异常告警中心</h2><p>实时检测按会话选择的算法窗口执行；规则告警和算法诊断结果分别展示。</p></div><el-button @click="loadSessions">刷新会话</el-button></div><el-card><el-form inline><el-form-item label="实时采集会话"><el-select v-model="sessionId" filterable clearable placeholder="请选择本次采集会话" @change="selectSession"><el-option v-for="s in sessions" :key="s.id" :value="s.id" :label="`${s.name} / ${labels[s.state]} / ${s.sample_count} 条 / ${algorithmLabels[s.detection_algorithm]||'规则'}`"/></el-select></el-form-item><el-form-item label="实时检测"><el-switch v-model="enabled" :disabled="!sessionId" active-text="已启用" inactive-text="未启用" @change="changeMonitoring"/></el-form-item></el-form><el-alert v-if="!sessionId" title="当前没有监测会话,请在开始采集后选择本次会话" type="info" :closable="false"/><el-alert v-else-if="!enabled" title="当前会话尚未启用异常检测" type="warning" :closable="false"/><el-alert v-else :title="state==='live'?'正在连续检测实时数据':'检测已启用,等待实时数据接入'" :type="state==='live'?'success':'info'" :closable="false"/></el-card><div class="stats"><el-card><small>会话状态</small><strong>{{labels[state]||'未选择'}}</strong></el-card><el-card><small>实时样本</small><strong>{{sampleCount}}</strong></el-card><el-card><small>告警数量</small><strong class="danger">{{alarms.length}}</strong></el-card><el-card><small>检测算法</small><strong>{{algorithmLabels[algorithm]||algorithm||'规则'}}</strong></el-card></div><el-card><template #header><b>算法窗口诊断结果</b></template><el-empty v-if="!results.length" description="窗口未满或暂无算法结果"/><el-table v-else :data="results" stripe><el-table-column prop="created_at" label="检测时间" width="190"><template #default="s">{{new Date(s.row.created_at).toLocaleString()}}</template></el-table-column><el-table-column label="算法"><template #default="s">{{algorithmLabels[s.row.algorithm]||s.row.algorithm}}</template></el-table-column><el-table-column prop="decision" label="判定"/><el-table-column prop="fault_name" label="结果"/><el-table-column prop="confidence" label="置信度"/><el-table-column label="窗口"><template #default="s">{{s.row.window_start}} ~ {{s.row.window_end}}</template></el-table-column></el-table></el-card><el-card><template #header><b>规则告警记录</b></template><el-empty v-if="!alarms.length" description="暂无规则告警"/><el-table v-else :data="alarms" stripe><el-table-column prop="created_at" label="告警时间" width="190"><template #default="s">{{new Date(s.row.created_at).toLocaleString()}}</template></el-table-column><el-table-column prop="severity" label="等级" width="90"><template #default="s"><el-tag :type="s.row.severity==='critical'?'danger':'warning'">{{severityLabels[s.row.severity]||s.row.severity}}</el-tag></template></el-table-column><el-table-column prop="fault_name" label="诊断故障"/><el-table-column label="异常信号" width="120"><template #default="s">{{signalLabels[s.row.signal]||s.row.signal}}</template></el-table-column><el-table-column label="检测依据"><template #default="s">{{signalLabels[s.row.signal]||s.row.signal}}={{s.row.value}},阈值 {{operators[s.row.operator]}}{{s.row.threshold}}</template></el-table-column><el-table-column prop="isolation_target" label="隔离对象"/><el-table-column prop="health_index" label="健康指数" width="100"/></el-table></el-card></div></template>
<script setup>import{ref,onMounted,onUnmounted}from'vue';import{ElMessage}from'element-plus';const LIVE_SOURCE_KEY='phm-live-source',sessions=ref([]),sessionId=ref(null),enabled=ref(false),state=ref(''),sampleCount=ref(0),alarms=ref([]),results=ref([]),algorithm=ref('rules'),cursor=ref(0);const labels={waiting:'等待数据',live:'正在接收',stale:'接收中断',closed:'采集结束'},algorithmLabels={rules:'基础规则',hier14:'Hier14 分层诊断',msfg_teams_rt:'MSFG + TEAMS-RT',pca_iforest:'PCA-iForest'},signalLabels={algorithm:'算法',pressure:'压力',temperature:'温度',bus_voltage:'母线电压',battery_capacity:'电池容量',attitude_error:'姿态误差',control_error:'控制误差',current:'电流',voltage:'电压',HI_norm:'健康指数'},severityLabels={critical:'严重',warning:'警告',info:'提示'},operators={gt:'>',gte:'≥',lt:'<',lte:'≤',eq:'='};let timer,generation=0;async function api(url,body){const token=document.cookie.split('; ').find(x=>x.startsWith('csrftoken='))?.slice(10);const r=await fetch(url,{credentials:'include',...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json',...(token?{'X-CSRFToken':decodeURIComponent(token)}:{})},body:JSON.stringify(body)}:{})});const j=await r.json();if(!r.ok)throw Error(j.detail||j.error);return j}async function loadSessions(){try{sessions.value=await api('/api/v1/phm/telemetry/sessions/')}catch(e){ElMessage.error(e.message)}}function clearCurrent(){generation++;clearTimeout(timer);enabled.value=false;state.value='';sampleCount.value=0;alarms.value=[];results.value=[];algorithm.value='rules';cursor.value=0}function selectSession(){clearCurrent();if(!sessionId.value)return;const s=sessions.value.find(x=>x.id===sessionId.value);enabled.value=!!s?.monitoring_enabled;state.value=s?.state||'';sampleCount.value=s?.sample_count||0;algorithm.value=s?.detection_algorithm||'rules';if(s?.state!=='closed')localStorage.setItem(LIVE_SOURCE_KEY,JSON.stringify({id:sessionId.value,name:s?.name||'',active:true}));poll(generation)}async function changeMonitoring(value){try{const s=await api(`/api/v1/phm/telemetry/sessions/${sessionId.value}/monitoring/`,{enabled:value});enabled.value=s.monitoring_enabled;ElMessage.success(value?'实时异常检测已启用':'实时异常检测已停止')}catch(e){enabled.value=!value;ElMessage.error(e.message)}}async function poll(g){if(!sessionId.value)return;try{const j=await api(`/api/v1/phm/telemetry/sessions/${sessionId.value}/alarms/?after=${cursor.value}`);if(g!==generation)return;state.value=j.session.state;sampleCount.value=j.session.sample_count;enabled.value=j.session.monitoring_enabled;algorithm.value=j.session.detection_algorithm||'rules';results.value=j.detection_results||[];if(j.results.length){cursor.value=j.next_cursor;alarms.value=[...j.results.reverse(),...alarms.value].slice(0,500)}}catch(e){if(g===generation)ElMessage.error(e.message)}if(g===generation&&state.value!=='closed')timer=setTimeout(()=>poll(g),1000)}onMounted(async()=>{await loadSessions();const saved=JSON.parse(localStorage.getItem(LIVE_SOURCE_KEY)||'null');const found=saved?.active&&sessions.value.find(s=>s.id===saved.id&&s.state!=='closed');if(found){sessionId.value=found.id;selectSession()}else{localStorage.removeItem(LIVE_SOURCE_KEY);clearCurrent()}});onUnmounted(()=>clearCurrent())</script>
<style scoped>.page{max-width:1400px}.head{display:flex;justify-content:space-between;align-items:start;margin-bottom:18px}.head p{color:#718198}.el-select{width:360px}.el-alert{margin-top:12px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:16px 0}.stats small,.stats strong{display:block}.stats strong{font-size:24px;margin-top:8px}.danger{color:#e34d59}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}}</style>
